#!/usr/bin/env node
// Fetches the pinned p5.js distribution at build time and embeds it
// verbatim in the app as a generated TS string
// (src/utils/editor/p5-runtime.generated.ts). Nothing is vendored in
// the repo (generated file is gitignored): the fetch happens in
// postinstall/start so the app works offline and a content-pack
// update can never ship a broken or incompatible p5 build.
//
// No custom transpilation: p5.min.js is shipped unmodified. The
// targeted modern WebView (Baseline, Chrome 90+ / iOS 16.4+) parses
// ES2022 syntax natively (named capture groups, Unicode property
// escapes, etc.). JS built-ins are polyfilled by core-js (see
// scripts/bundle-polyfill.mjs), not by hand-written shims.
// Run via: npm run bundle-p5
import fs from "fs";
import https from "https";
import path from "path";

const PINNED_P5_VERSION = "2.4.0-rc.1";
const CDN_URL = `https://cdn.jsdelivr.net/npm/p5@${PINNED_P5_VERSION}/lib/p5.min.js`;
const MIN_BUNDLE_BYTES = 100_000;
const P5_BANNER_RE = /^\/\*![\s\S]*?\*\//;

function download(url) {
  return new Promise((resolve, reject) => {
    https
      .get(url, (res) => {
        if (res.statusCode && res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          return download(res.headers.location).then(resolve).catch(reject);
        }
        if (res.statusCode !== 200) {
          return reject(new Error(`HTTP ${res.statusCode} fetching ${url}`));
        }
        const chunks = [];
        res.on("data", (d) => chunks.push(d));
        res.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
      })
      .on("error", reject);
  });
}

function validateRuntime(runtime) {
  if (!runtime.startsWith(`/*! p5.js v${PINNED_P5_VERSION}`)) {
    throw new Error("Downloaded p5.js runtime lost its version banner.");
  }
  if (runtime.length < MIN_BUNDLE_BYTES) {
    throw new Error(`Downloaded p5.js runtime is incomplete (${runtime.length} bytes).`);
  }
  if (!runtime.trimEnd().endsWith(");")) {
    throw new Error("Downloaded p5.js runtime is truncated.");
  }
  // Parse check in a modern engine to catch outright syntax errors.
  // No downleveling is performed: modern WebViews run this verbatim.
  // eslint-disable-next-line no-new-func
  new Function(runtime);
}

async function buildRuntime(source) {
  const bannerMatch = source.match(P5_BANNER_RE);
  if (!bannerMatch) {
    throw new Error("p5.js download is missing its version banner.");
  }
  if (!bannerMatch[0].includes(`p5.js v${PINNED_P5_VERSION}`)) {
    throw new Error(`p5.js banner does not match pinned version ${PINNED_P5_VERSION}.`);
  }
  const runtime = source.trim() + "\n";
  validateRuntime(runtime);
  return runtime;
}

async function main() {
  const outFile = path.resolve("src/utils/editor/p5-runtime.generated.ts");
  console.log(`[bundle-p5] p5.js version: ${PINNED_P5_VERSION}`);
  console.log(`[bundle-p5] Fetching ${CDN_URL}`);
  const source = await download(CDN_URL);
  const runtime = await buildRuntime(source);
  const tsContent = `// Auto-generated by scripts/bundle-p5.mjs — DO NOT EDIT
export const P5_RUNTIME_VERSION = ${JSON.stringify(PINNED_P5_VERSION)};
export const P5_RUNTIME_SOURCE = ${JSON.stringify(runtime)};
`;
  fs.writeFileSync(outFile, tsContent, "utf-8");
  console.log(`[bundle-p5] Wrote ${outFile} (${runtime.length} bytes, verbatim)`);
}

main().catch((err) => {
  console.error("[bundle-p5] FAILED:", err);
  process.exit(1);
});
